using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    // .NET 9 breaking change: DropDownControl(null) now throws ArgumentNullException.
    // Guard against null before calling.
    public static void SafeDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
        else
        {
            editorService.CloseDropDown();
        }
    }

    // .NET 9 breaking change: StatusStrip default renderer changed.
    // Opt into the legacy Professional renderer for consistent appearance.
    public static StatusStrip CreateStatusStrip()
    {
        var strip = new StatusStrip();
        strip.RenderMode = ToolStripRenderMode.Professional;
        return strip;
    }
}

